<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {GitBranch,Minus,Plus,Maximize,LocateFixed,List,ArrowLeft,Archive,Undo2,Pencil,Star,History,Trash2} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import type {Document,LocalStory,ProgressAnchor} from '../domain/local-contract'
import type {LocalBranch} from './contract'
import {contentGraph,type GraphParagraphProof} from './content-graph'
import {graphParagraphProofs} from './content-graph-runtime'
import {progressKey} from './runtime'
import {mainLineKey,setMainReadingLine,type MainReadingLine} from './main-line'
import ComparisonPanel from './ComparisonPanel.vue'
import HistoryPanel from './HistoryPanel.vue'
import BranchDeletePanel from './BranchDeletePanel.vue'
import {clusterTimeline,type TimelineCluster} from './cluster-view'
const store=useLocal(),route=useRoute(),router=useRouter(),storyId=String(route.params.storyId),story=ref<Document<LocalStory>|null>(null),branches=ref<Document<LocalBranch>[]>([]),progress=ref(new Map<string,ProgressAnchor>()),selected=ref(typeof route.query.branch==='string'?route.query.branch:''),error=ref(''),busy=ref(true),canvas=ref<HTMLElement>(),size=ref({width:900,height:560}),camera=ref({x:100,y:240,zoom:1}),listOpen=ref(false),listPage=ref(0),editing=ref<Document<LocalBranch>|null>(null),name=ref(''),saving=ref(false),showArchived=ref(false),hovered=ref('')
let loadControl=new AbortController(),loadEpoch=0
let disposed=false,observer:ResizeObserver|null=null,drag:{x:number;y:number;cx:number;cy:number;id:number;moved:boolean}|null=null
const historyOpen=ref(false),deleteId=ref('')
async function deleted(){selected.value='';await load()}
function committed(event:Event){const detail=(event as CustomEvent<{vaultId:string;kinds:string[]}>).detail;if(!disposed&&detail?.vaultId===store.vault?.id&&detail.kinds.includes('branch'))void load()}
const graphProofs=ref(new Map<string,GraphParagraphProof>()),comparisonOpen=ref(false),mainLine=ref<Document<MainReadingLine>|null>(null)
async function promote(){const vault=store.vault;if(!vault||saving.value)return;saving.value=true;try{await setMainReadingLine(vault,storyId,selected.value||null,mainLine.value?.revision||0);if(!disposed&&store.vault===vault)await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
const pointers=new Map<number,{x:number;y:number}>();let pinch:{distance:number;zoom:number;x:number;y:number;centerX:number;centerY:number}|null=null
const visibleBranches=computed(()=>branches.value.filter(row=>showArchived.value||!row.value.archived||row.id===selected.value||row.id===mainLine.value?.value.branchId))
const graph=computed(()=>contentGraph(storyId,story.value?.value.chapters||[],visibleBranches.value,graphProofs.value)),activePath=computed(()=>new Set(graph.value.paths.get(selected.value||storyId)||[]))
const positions=computed(()=>{const rows=new Map<string,number>([[storyId,0],...visibleBranches.value.map((row,index)=>[row.id,index+1] as [string,number])]);return new Map(graph.value.nodes.map(node=>[node.id,{x:node.column*180,y:(rows.get(node.lineId||storyId)||0)*170}]))})
const aggregated=computed(()=>camera.value.zoom<.25)
const clusters=computed(()=>clusterTimeline(graph.value.nodes,graph.value.edges,positions.value,camera.value.zoom))
const shownClusters=computed(()=>{const c=camera.value;return clusters.value.groups.filter(g=>g.point.x*c.zoom+c.x>-60&&g.point.x*c.zoom+c.x<size.value.width+60&&g.point.y*c.zoom+c.y>-60&&g.point.y*c.zoom+c.y<size.value.height+60)})
const clusterById=computed(()=>new Map(clusters.value.groups.map(g=>[g.id,g])))
const firstClusters=computed(()=>{const first=new Map<string|null,string>();for(const group of clusters.value.groups)if(!first.has(group.lineId))first.set(group.lineId,group.id);return new Set(first.values())})
function compactLineName(id:string|null){const chars=Array.from(branchName(id));return chars.slice(0,8).join('')+(chars.length>8?'…':'')}
function clusterPath(edge:{from:string;to:string}){const a=clusterById.value.get(edge.from)!.point,b=clusterById.value.get(edge.to)!.point;return `M ${a.x} ${a.y} C ${a.x+70} ${a.y}, ${b.x-70} ${b.y}, ${b.x} ${b.y}`}
function expandCluster(group:TimelineCluster){const z=Math.min(1.2,Math.max(.3,(size.value.width-140)/(Math.max(1,group.last-group.first)*180+80))),points=group.ids.map(id=>positions.value.get(id)!),point={x:points.reduce((sum,p)=>sum+p.x,0)/points.length,y:points.reduce((sum,p)=>sum+p.y,0)/points.length};camera.value={x:size.value.width/2-point.x*z,y:size.value.height/2-point.y*z,zoom:z}}
const drawnNodes=computed(()=>{const c=camera.value;return graph.value.nodes.filter(node=>{const p=positions.value.get(node.id)!;return p.x*c.zoom+c.x>-180&&p.x*c.zoom+c.x<size.value.width+180&&p.y*c.zoom+c.y>-100&&p.y*c.zoom+c.y<size.value.height+100})})
const drawnIds=computed(()=>new Set(drawnNodes.value.map(n=>n.id)))
const drawnEdges=computed(()=>graph.value.edges.filter(edge=>drawnIds.value.has(edge.from)||drawnIds.value.has(edge.to)))
const miniBounds=computed(()=>{let x=180,y=170;for(const point of positions.value.values()){x=Math.max(x,point.x);y=Math.max(y,point.y)}return `-60 -60 ${x+120} ${y+120}`})
const listedNodes=computed(()=>{const path=graph.value.paths.get(selected.value||storyId)||[],lookup=new Map(graph.value.nodes.map(n=>[n.id,n]));return path.map(id=>lookup.get(id)!)})
const listed=computed(()=>selected.value?branches.value.find(row=>row.id===selected.value)?.value.chapters||[]:story.value?.value.chapters||[])
const branchName=(id:string|null)=>id?branches.value.find(row=>row.id===id)?.value.name||'故事线':'原文'
function nodeTitle(node:typeof graph.value.nodes[number]){const path=graph.value.paths.get(node.lineId||storyId)||[],anchor=progress.value.get(node.lineId||storyId),chapter=listedFor(node.lineId).find(c=>c.paragraphIds.includes(anchor?.paragraphId||'')),read=chapter?listedFor(node.lineId).findIndex(c=>c.id===chapter.id):-1;return node.lineId||node.index<=read?node.title:'第 '+(path.indexOf(node.id)+1)+' 章'}
function listedFor(id:string|null){return id?branches.value.find(row=>row.id===id)?.value.chapters||[]:story.value?.value.chapters||[]}
function currentNode(node:typeof graph.value.nodes[number]){const anchor=progress.value.get(selected.value||storyId);return !!anchor&&listed.value.find(c=>c.id===node.chapterId)?.paragraphIds.includes(anchor.paragraphId)&&activePath.value.has(node.id)}
function edgePath(edge:typeof graph.value.edges[number]){const a=positions.value.get(edge.from)!,b=positions.value.get(edge.to)!;return `M${a.x},${a.y} C${a.x+90},${a.y} ${b.x-90},${b.y} ${b.x},${b.y}`}
function zoom(factor:number,x=size.value.width/2,y=size.value.height/2){const c=camera.value,n=Math.max(.001,Math.min(2.5,c.zoom*factor)),ratio=n/c.zoom;camera.value={x:x-(x-c.x)*ratio,y:y-(y-c.y)*ratio,zoom:n}}
function wheel(event:WheelEvent){event.preventDefault();const rect=canvas.value?.getBoundingClientRect();zoom(Math.exp(-event.deltaY*.0015),event.clientX-(rect?.left||0),event.clientY-(rect?.top||0))}
function down(event:PointerEvent){if(event.button!==0||event.target instanceof Element&&event.target.closest('[data-node],button,a,input,select'))return;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});canvas.value?.setPointerCapture(event.pointerId);if(pointers.size===2){const [a,b]=[...pointers.values()],rect=canvas.value!.getBoundingClientRect();pinch={distance:Math.hypot(a!.x-b!.x,a!.y-b!.y),zoom:camera.value.zoom,x:camera.value.x,y:camera.value.y,centerX:(a!.x+b!.x)/2-rect.left,centerY:(a!.y+b!.y)/2-rect.top};drag=null}else if(pointers.size===1)drag={x:event.clientX,y:event.clientY,cx:camera.value.x,cy:camera.value.y,id:event.pointerId,moved:false}}
function move(event:PointerEvent){if(!pointers.has(event.pointerId))return;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(pinch&&pointers.size===2){const [a,b]=[...pointers.values()],rect=canvas.value!.getBoundingClientRect(),n=Math.max(.001,Math.min(2.5,pinch.zoom*Math.hypot(a!.x-b!.x,a!.y-b!.y)/Math.max(1,pinch.distance))),ratio=n/pinch.zoom;camera.value={x:(a!.x+b!.x)/2-rect.left-(pinch.centerX-pinch.x)*ratio,y:(a!.y+b!.y)/2-rect.top-(pinch.centerY-pinch.y)*ratio,zoom:n};return}if(!drag||event.pointerId!==drag.id)return;const dx=event.clientX-drag.x,dy=event.clientY-drag.y;drag.moved ||=Math.abs(dx)+Math.abs(dy)>5;camera.value={...camera.value,x:drag.cx+dx,y:drag.cy+dy}}
function up(event:PointerEvent){pointers.delete(event.pointerId);pinch=null;drag=null;if(pointers.size===1){const [id,point]=[...pointers.entries()][0]!;drag={id,x:point.x,y:point.y,cx:camera.value.x,cy:camera.value.y,moved:true}}}
function fit(){const maxX=Math.max(180,...[...positions.value.values()].map(p=>p.x)),maxY=Math.max(170,...[...positions.value.values()].map(p=>p.y)),z=Math.max(.001,Math.min(1.2,(size.value.width-200)/(maxX+80),(size.value.height-160)/(maxY+50)));camera.value={x:100,y:70,zoom:z}}
function locate(){const path=graph.value.paths.get(selected.value||storyId)||[],anchor=progress.value.get(selected.value||storyId),chapter=listed.value.find(c=>c.paragraphIds.includes(anchor?.paragraphId||'')),id=path.find(id=>graph.value.nodes.find(n=>n.id===id)?.chapterId===chapter?.id)||path.at(-1),point=id?positions.value.get(id):null;if(point)camera.value={x:size.value.width/2-point.x,y:size.value.height/2-point.y,zoom:1}}
function nodeDestination(node:typeof graph.value.nodes[number]){const line=activePath.value.has(node.id)?selected.value||null:node.lineId,target=node.targets[line||storyId];return {path:'/local/read/'+storyId,query:{branch:line||undefined,paragraph:target?.paragraphId,offset:target?String(target.offset):undefined}}}
function openNode(node:typeof graph.value.nodes[number]){void router.push(nodeDestination(node))}
async function load(){const vault=store.vault;if(!vault)return;loadControl.abort();loadControl=new AbortController();const signal=loadControl.signal,token=++loadEpoch;try{const [book,lines,anchors,primary]=await Promise.all([vault.read<LocalStory>(storyId),vault.list<LocalBranch>('branch'),vault.list<ProgressAnchor>('progress'),vault.read<MainReadingLine>(mainLineKey(storyId))]);if(disposed||store.vault!==vault||token!==loadEpoch)return;if(!book||book.kind!=='story')throw new Error('找不到这本故事');const owned=lines.filter(row=>row.value.storyId===storyId),proofs=await graphParagraphProofs(vault,[...book.value.chapters,...owned.flatMap(row=>row.value.chapters)],signal);if(disposed||store.vault!==vault||token!==loadEpoch)return;if((await vault.read(book.id))?.revision!==book.revision)throw new Error('故事版本已变化，请重新打开图谱');for(const row of owned)if((await vault.read(row.id))?.revision!==row.revision)throw new Error('故事线版本已变化，请重新打开图谱');graphProofs.value=proofs;story.value=book;mainLine.value=primary;branches.value=owned.sort((a,b)=>a.value.createdAt.localeCompare(b.value.createdAt));progress.value=new Map(anchors.filter(row=>row.value.storyId===storyId).map(row=>[row.value.branchId||storyId,row.value]));if(selected.value&&!branches.value.some(row=>row.id===selected.value))selected.value=''}catch(e){if(token===loadEpoch&&!signal.aborted)error.value=(e as Error).message}finally{if(token===loadEpoch)busy.value=false}}
async function archive(row:Document<LocalBranch>){const vault=store.vault;if(!vault)return;try{await vault.commit(crypto.randomUUID(),'branch',row.id,row.revision,{...row.value,archived:!row.value.archived});if(row.id===selected.value&&!row.value.archived)selected.value='';await load()}catch(e){error.value=(e as Error).message}}
async function rename(){const vault=store.vault,row=editing.value;if(!vault||!row||saving.value)return;saving.value=true;try{await vault.commit(crypto.randomUUID(),'branch',row.id,row.revision,{...row.value,name:name.value.trim()});editing.value=null;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(async()=>{window.addEventListener('reader-private-commit',committed);await load();if(disposed)return;observer=new ResizeObserver(entries=>{const rect=entries[0]?.contentRect;if(rect){const changed=Math.abs(size.value.width-rect.width)>40;size.value={width:rect.width,height:rect.height};if(changed)fit()}});if(canvas.value)observer.observe(canvas.value);requestAnimationFrame(()=>{if(!disposed)fit()})})
onUnmounted(()=>{window.removeEventListener('reader-private-commit',committed);disposed=true;loadControl.abort();observer?.disconnect()})
</script>
<template><section class="final-lines-page"><header class="final-lines-heading"><RouterLink :to="{path:'/local/read/'+storyId,query:{branch:selected||undefined}}" class="final-icon-button" aria-label="返回阅读"><ArrowLeft :size="20"/></RouterLink><div><small>{{story?.value.title}}</small><h1>故事线</h1></div><button aria-label="打开故事线列表" @click="listOpen=true"><List :size="20"/></button></header><p v-if="error" class="final-error" role="alert">{{error}}</p><div class="final-lines-shell"><nav class="final-line-chips" aria-label="故事线"><button :aria-pressed="!selected" @click="selected='';listPage=0">原文<Star v-if="!mainLine?.value.branchId" :size="13" aria-label="主要阅读线"/></button><button v-for="row in visibleBranches" :key="row.id" :aria-pressed="selected===row.id" @click="selected=row.id;listPage=0">{{row.value.name}}<Star v-if="mainLine?.value.branchId===row.id" :size="13" aria-label="主要阅读线"/><Archive v-if="row.value.archived" :size="13"/></button></nav><div ref="canvas" class="final-lines-canvas" :class="{'is-dragging':drag}" aria-label="可拖动的故事线图谱" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @wheel="wheel"><p v-if="busy" role="status">正在展开故事…</p><svg v-else width="100%" height="100%" role="group" aria-label="章节和故事分叉"><g :transform="`translate(${camera.x} ${camera.y}) scale(${camera.zoom})`"><template v-if="!aggregated"><path v-for="edge in drawnEdges" :key="edge.from+'>'+edge.to" :d="edgePath(edge)" class="final-line-edge" :class="{'is-active':activePath.has(edge.from)&&activePath.has(edge.to)}"/><g v-for="node in drawnNodes" :key="node.id" data-node="true" class="final-line-node" :class="{'is-active':activePath.has(node.id),'is-current':currentNode(node),'is-hovered':hovered===node.id,'is-ai':!!node.lineId}" :transform="`translate(${positions.get(node.id)?.x} ${positions.get(node.id)?.y})`" tabindex="0" role="button" :aria-label="nodeTitle(node)+' · '+branchName(node.lineId)" @click.stop="openNode(node)" @keydown.enter.prevent="openNode(node)" @keydown.space.prevent="openNode(node)" @mouseenter="hovered=node.id" @mouseleave="hovered=''"><circle class="final-node-halo" :r="Math.max(35,22/camera.zoom)"/><circle class="final-node-dot" r="16"/><circle v-if="currentNode(node)" r="5" fill="var(--canvas)"/><text v-if="camera.zoom>.45" y="51" text-anchor="middle">{{nodeTitle(node)}}</text><text v-if="camera.zoom>.65&&node.lineId&&node.index===(branches.find(row=>row.id===node.lineId)?.value.prefixChapters.length||0)" y="-43" text-anchor="middle" class="final-node-line-name">{{branchName(node.lineId)}}</text><text v-if="camera.zoom>.65&&node.boundary" y="-24" text-anchor="middle" class="final-node-line-name">{{node.boundary}}</text><title>{{nodeTitle(node)}} · {{branchName(node.lineId)}}</title></g></template><template v-else><path v-for="edge in clusters.edges" :key="edge.from+edge.to" :d="clusterPath(edge)" class="final-line-edge final-cluster-edge" :class="{'is-active':clusterById.get(edge.from)?.ids.some(id=>activePath.has(id))&&clusterById.get(edge.to)?.ids.some(id=>activePath.has(id))}"/><g v-for="group in shownClusters" :key="group.id" data-node="true" data-cluster="true" :data-last-index="group.last" :transform="`translate(${group.point.x} ${group.point.y})`" role="button" tabindex="0" :aria-label="branchName(group.lineId)+' 第 '+(group.first+1)+'—'+(group.last+1)+' 章，展开'" @click.stop="expandCluster(group)" @keydown.enter.prevent="expandCluster(group)" @keydown.space.prevent="expandCluster(group)"><g :transform="`scale(${1/camera.zoom})`" class="final-line-cluster" :class="{'is-active':group.ids.some(id=>activePath.has(id))}"><text v-if="firstClusters.has(group.id)" text-anchor="middle" y="-34" class="cluster-line-name">{{compactLineName(group.lineId)}}</text><circle r="22"/><text text-anchor="middle" y="4">{{group.ids.length}}</text><text text-anchor="middle" y="39" class="cluster-range">{{group.first+1}}—{{group.last+1}}</text></g></g></template></g></svg><div class="final-lines-camera"><button aria-label="缩小图谱" @click="zoom(.8)"><Minus :size="17"/></button><span>{{Math.round(camera.zoom*100)}}%</span><button aria-label="放大图谱" @click="zoom(1.25)"><Plus :size="17"/></button><button aria-label="全览故事线" @click="fit"><Maximize :size="17"/></button><button aria-label="定位阅读位置" @click="locate"><LocateFixed :size="17"/></button></div><svg class="final-lines-minimap" :viewBox="miniBounds" aria-hidden="true"><path v-for="edge in graph.edges" :key="edge.from+'>'+edge.to" :d="edgePath(edge)" stroke="var(--edge)" fill="none" stroke-width="5"/><circle v-for="node in graph.nodes.slice(0,500)" :key="node.id" :cx="positions.get(node.id)?.x" :cy="positions.get(node.id)?.y" r="9" :fill="activePath.has(node.id)?'var(--accent)':'var(--muted)'"/></svg></div></div><div class="final-lines-foot"><span><GitBranch :size="16"/>{{branches.length+1}} 条故事线</span><button :disabled="saving||(mainLine?.value.branchId||'')===selected" @click="promote"><Star :size="15"/>{{(mainLine?.value.branchId||'')===selected?'主要阅读线':'设为主要阅读线'}}</button><button @click="historyOpen=true"><History :size="15"/>历史版本</button><button :disabled="!branches.length" @click="comparisonOpen=true">比较</button><label class="final-check"><input v-model="showArchived" type="checkbox">已归档</label><template v-if="selected"><button @click="editing=branches.find(row=>row.id===selected)||null;name=editing?.value.name||''"><Pencil :size="15"/>重命名</button><button @click="archive(branches.find(row=>row.id===selected)!)"><component :is="branches.find(row=>row.id===selected)?.value.archived?Undo2:Archive" :size="15"/>{{branches.find(row=>row.id===selected)?.value.archived?'恢复':'归档'}}</button><button :disabled="saving" @click="deleteId=selected"><Trash2 :size="15"/>删除</button></template></div><Sheet v-if="listOpen" title="章节与故事线" @close="listOpen=false"><div class="final-chapter-list"><label>故事线<select v-model="selected" @change="listPage=0"><option value="">原文</option><option v-for="row in branches" :key="row.id" :value="row.id">{{row.value.name}}{{row.value.archived?' · 已归档':''}}</option></select></label><RouterLink v-for="node in listedNodes.slice(listPage*80,listPage*80+80)" :key="node.id" class="final-text-link" :to="nodeDestination(node)">{{nodeTitle(node)}}<small v-if="node.boundary"> · {{node.boundary}}</small></RouterLink><div class="final-page-actions"><button :disabled="listPage===0" @click="listPage--">上一页</button><button :disabled="(listPage+1)*80>=listedNodes.length" @click="listPage++">下一页</button></div></div></Sheet><BranchDeletePanel v-if="deleteId" :branch-id="deleteId" @close="deleteId=''" @deleted="deleted"/><HistoryPanel v-if="historyOpen" :story-id="storyId" :branch-id="selected||null" @close="historyOpen=false"/><ComparisonPanel v-if="comparisonOpen" :story-id="storyId" :branches="branches" :selected="selected" @close="comparisonOpen=false"/><Sheet v-if="editing" title="重命名故事线" @close="!saving&&(editing=null)"><form @submit.prevent="rename"><label>名称<input v-model="name" maxlength="200" required></label><button class="final-primary" :disabled="saving||!name.trim()">保存</button></form></Sheet></section></template>
<style scoped>
.final-line-cluster{cursor:pointer}.final-line-cluster circle{fill:var(--canvas);stroke:var(--edge);stroke-width:1.5}.final-line-cluster.is-active circle{fill:var(--wash);stroke:var(--accent)}.final-line-cluster text{fill:var(--accent);font:12px var(--font-sans,sans-serif)}.final-cluster-edge{stroke:var(--muted);opacity:.65}.final-line-cluster .cluster-line-name{font-size:11px;fill:var(--ink)}.final-line-cluster .cluster-range{fill:var(--quiet);font-size:10px}

.final-lines-page{max-width:1440px;margin:auto}.final-lines-heading{display:flex;align-items:center;gap:16px;margin-bottom:28px}.final-lines-heading>div{flex:1}.final-lines-heading small{color:var(--muted)}.final-lines-heading h1{font:36px serif;margin:6px 0}.final-lines-shell{border:1px solid var(--edge);border-radius:24px;background:var(--canvas);overflow:hidden}.final-line-chips{display:flex;gap:8px;padding:20px;overflow:auto;border-bottom:1px solid var(--edge)}.final-line-chips button{white-space:nowrap;border-radius:999px!important;font-size:13px}.final-line-chips button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}.final-lines-canvas{height:min(68vh,760px);min-height:420px;position:relative;touch-action:none;cursor:grab;overflow:hidden;background:radial-gradient(circle,var(--edge) .6px,transparent .7px);background-size:24px 24px}.final-lines-canvas.is-dragging{cursor:grabbing}.final-line-edge{fill:none;stroke:var(--edge);stroke-width:1.4;vector-effect:non-scaling-stroke;transition:stroke .3s,opacity .3s}.final-line-edge.is-active{stroke:var(--accent);opacity:.65}.final-line-node{cursor:pointer;outline:none}.final-node-halo{fill:var(--accent);opacity:0;transform:scale(.5);transition:opacity .25s,transform .45s cubic-bezier(.2,1.5,.3,1)}.final-node-dot{fill:var(--canvas);stroke:var(--muted);stroke-width:2;transition:fill .25s,stroke .25s,transform .4s cubic-bezier(.2,1.5,.3,1)}.final-line-node.is-active .final-node-dot{stroke:var(--accent)}.final-line-node.is-ai .final-node-dot{fill:var(--wash)}.final-line-node.is-current .final-node-dot{fill:var(--accent)}.final-line-node.is-hovered .final-node-dot,.final-line-node:focus .final-node-dot{transform:scale(1.18);fill:var(--wash)}.final-line-node.is-hovered .final-node-halo,.final-line-node:focus .final-node-halo,.final-line-node.is-current .final-node-halo{opacity:.09;transform:scale(1)}.final-line-node text{fill:var(--ink);font:15px serif;pointer-events:none}.final-line-node text.final-node-line-name{fill:var(--accent);font:12px system-ui}.final-lines-camera{position:absolute;bottom:20px;left:20px;display:flex;align-items:center;gap:2px;background:var(--canvas);border:1px solid var(--edge);border-radius:14px;padding:4px;box-shadow:0 4px 20px #29241909}.final-lines-camera button{border:0!important;width:36px;height:36px;justify-content:center;padding:0!important}.final-lines-camera span{font-size:11px;min-width:38px;text-align:center;color:var(--muted)}.final-lines-minimap{position:absolute;right:20px;bottom:20px;width:140px;height:80px;background:var(--wash);border:1px solid var(--edge);border-radius:12px;opacity:.8;pointer-events:none}.final-lines-foot{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:16px;font-size:12px;color:var(--muted)}.final-lines-foot>span{display:flex;align-items:center;gap:8px;margin-right:auto}.final-lines-foot button{font-size:12px}@media(max-width:600px){.final-lines-heading h1{font-size:28px}.final-lines-canvas{height:62vh;min-height:380px}.final-line-chips{padding:12px}.final-lines-minimap{width:80px;right:12px;bottom:16px}.final-lines-camera{left:12px;bottom:16px}}@media(prefers-reduced-motion:reduce){.final-line-edge,.final-node-dot,.final-node-halo{transition:none}}
</style>
